+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_EACH_TEST_METHOD)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Autowired
+    private MessageService messageService;
+
+    @BeforeEach
+    void openView() {
+        navigate(ContactView.class);
+    }
+
+    private TextField nameField() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField emailField() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phoneField() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea messageField() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button sendButton() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private void clickAboutLink() {
+        RouterLink link = find(RouterLink.class).withText("About").single();
+        test(link).click();
+    }
+
+    @Test
+    void showsHeadingLinkAndEmptyForm() {
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+
+        assertTrue(nameField().isEmpty());
+        assertTrue(emailField().isEmpty());
+        assertTrue(phoneField().isEmpty());
+        assertTrue(messageField().isEmpty());
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void emptyFormFailsValidation() {
+        sendButton().click();
+
+        assertTrue(nameField().isInvalid());
+        assertEquals("Name is required", nameField().getErrorMessage());
+
+        assertTrue(emailField().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", emailField().getErrorMessage());
+
+        assertTrue(messageField().isInvalid());
+        assertEquals("Message is required", messageField().getErrorMessage());
+
+        assertTrue(sendButton().isEnabled());
+        assertEquals(0, messageService.list().size());
+    }
+
+    @Test
+    void invalidEmailFormatIsRejected() {
+        nameField().setValue("Ann");
+        emailField().setValue("not-an-email");
+        messageField().setValue("Hello there");
+
+        sendButton().click();
+
+        assertTrue(emailField().isInvalid());
+        assertEquals("Enter a valid e-mail address", emailField().getErrorMessage());
+        assertEquals(0, messageService.list().size());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        nameField().setValue("Ann");
+        phoneField().setValue("12345");
+        messageField().setValue("x".repeat(501));
+
+        sendButton().click();
+
+        assertTrue(messageField().isInvalid());
+        assertEquals("Message must be at most 500 characters", messageField().getErrorMessage());
+        assertEquals(0, messageService.list().size());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToSend() {
+        nameField().setValue("Ann");
+        phoneField().setValue("12345");
+        messageField().setValue("Hello there");
+
+        sendButton().click();
+
+        assertEquals(1, messageService.list().size());
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void emailAloneIsEnoughAndFieldsClearAfterSend() {
+        nameField().setValue("Ann");
+        emailField().setValue("ann@example.com");
+        messageField().setValue("Hello there");
+
+        sendButton().click();
+
+        assertEquals(1, messageService.list().size());
+        ContactMessage stored = messageService.list().get(0);
+        assertEquals("Ann", stored.name());
+        assertEquals("ann@example.com", stored.email());
+        assertEquals("Hello there", stored.message());
+
+        assertTrue(nameField().isEmpty());
+        assertTrue(emailField().isEmpty());
+        assertTrue(phoneField().isEmpty());
+        assertTrue(messageField().isEmpty());
+
+        assertFalse(sendButton().isEnabled());
+
+        nameField().setValue("Bob");
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void enterKeySends() {
+        nameField().setValue("Ann");
+        phoneField().setValue("12345");
+        messageField().setValue("Hello there");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, messageService.list().size());
+    }
+
+    @Test
+    void newestMessageIsFirstInGrid() {
+        nameField().setValue("First");
+        phoneField().setValue("111");
+        messageField().setValue("first message");
+        sendButton().click();
+
+        nameField().setValue("Second");
+        phoneField().setValue("222");
+        messageField().setValue("second message");
+        sendButton().click();
+
+        assertEquals("Second", messageService.list().get(0).name());
+        assertEquals("First", messageService.list().get(1).name());
+    }
+
+    @Test
+    void nothingIsSentWhenValidationFails() {
+        messageField().setValue("");
+        sendButton().click();
+
+        assertEquals(0, messageService.list().size());
+        assertEquals("", nameField().getValue());
+    }
+
+    @Test
+    void navigatingAwayWithEmptyFormDoesNotShowDialog() {
+        clickAboutLink();
+
+        assertTrue(find(AboutView.class).exists());
+    }
+
+    @Test
+    void navigatingAwayWithUnsavedInputAsksFirst() {
+        nameField().setValue("Ann");
+
+        clickAboutLink();
+
+        Dialog dialog = find(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+
+        assertEquals("Ann", nameField().getValue());
+    }
+
+    @Test
+    void keepEditingClosesDialogAndStaysOnContact() {
+        nameField().setValue("Ann");
+        clickAboutLink();
+
+        find(Button.class).withText("Keep editing").single().click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertEquals("Ann", nameField().getValue());
+    }
+
+    @Test
+    void discardNavigatesAway() {
+        nameField().setValue("Ann");
+        clickAboutLink();
+
+        find(Button.class).withText("Discard").single().click();
+
+        assertTrue(find(AboutView.class).exists());
+    }
+}
